sys_script_include.script:
var EventProcessor = Class.create();
EventProcessor.prototype = {
    initialize: function() {
        this.repo = new EventRepository();
    },

    process: function(payload) {
        this.validate(payload);

        var eventID = this.repo.tryCreate(payload);
        if (!eventID)
            return {
                message: "Already processed"
            };

        try {
            var handlerFactory = new SourceHandlerFactory();
            var handler = handlerFactory.getHandler(payload.u_source);

            var handlerResult = handler.handle(payload);

            this.repo.markProcessed(eventID);

            return {
                handlerResult,
                eventID: eventID
            };

        } catch (err) {
            this.repo.markFailed(eventID, err.message);
			throw err;
        }

    },

    validate: function(payload) {
        if (!payload.u_source)
            throw new Error('Missing source!');

        if (!payload.u_trello_action_id)
            throw new Error('Missing Trello ID!');
    },
    type: 'EventProcessor'
};
